  function rowTable(head,rows){return '<div class="tablewrap"><table class="table v11-table"><thead><tr>'+head.map(function(x){return '<th>'+x+'</th>'}).join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
  function scope(){var c=R[A.role]||R.nurse;return '<div class="v11-scope"><span>当前用户：<b>'+c.user+'</b>　|　数据范围：<b>'+c.scope+'</b></span><span>最后同步：'+now()+'</span></div>'}
  function shell(){var c=R[A.role],nav=c.nav||[],go=A.role==='nurse'?'v14SetModule':'v141Module';return '<div class="brand">医路协同<small>患者诊疗流程协同与服务平台</small></div><div class="rolebox"><label>当前工作端</label><strong style="display:block;color:#fff;padding:8px 0">'+c.label+'</strong></div><div class="v11-primary-head">岗位工作模块</div><div class="v11-side-primary">'+nav.map(function(x){return '<button class="'+(S.module===x[0]?'on':'')+'" onclick="'+go+'(\''+x[0]+'\')"><span>▦</span>'+x[1]+'</button>'}).join('')+'</div><div class="foot">当前用户：'+c.user+'<br>数据范围：'+c.scope+'<br>'+B('退出登录','v141Logout()','btn sm')+'</div>'}
  function sub(){var a=(M[A.role]&&M[A.role][S.module])||[['overview','工作区']],go=A.role==='nurse'?'v14SetSub':'v141Sub';return '<aside class="v11-subnav"><h3>'+((R[A.role].nav.find(function(x){return x[0]===S.module})||['','工作区'])[1])+'</h3>'+a.map(function(x){return '<button class="v11-subbtn '+(S.sub===x[0]?'on':'')+'" onclick="'+go+'(\''+x[0]+'\')">'+x[1]+'</button>'}).join('')+'</aside>'}
  function commonPage(body){var c=R[A.role],m=(c.nav.find(function(x){return x[0]===S.module})||['','工作区'])[1],a=(M[A.role]&&M[A.role][S.module])||[['overview','工作区']],ss=a.find(function(x){return x[0]===S.sub})||a[0];return '<div class="v11-layout">'+sub()+'<main class="v11-work">'+scope()+(notice?'<div class="v11-info" style="margin-bottom:14px">'+e(notice)+'</div>':'')+body+'</main></div>'}
  function login(){return '<div class="v11-login" style="max-width:760px;margin:0 auto;padding-top:55px"><div class="brandmark">医路协同</div><div class="subtitle">三甲医院患者诊疗流程协同平台 · 统一登录入口</div><div class="v11-card"><h2>账号登录</h2><div class="v11-form"><label>账号 *</label><input id="v141Account" placeholder="nurse01 / outpatient01 / doctor01 / tech01 / admin01 / patient01"><label>密码 *</label><input id="v141Password" type="password" placeholder="演示密码 demo123"><label>医院 *</label><select id="v141Hospital"><option>云川市第一人民医院</option><option>云川市第二人民医院</option></select><label>科室/病区 *</label><select id="v141Dept"><option>8A 呼吸内科病区</option><option>门诊服务台</option><option>检验科</option><option>全院运营</option><option>患者本人</option></select><button class="btn primary" onclick="v141Login()">登录</button></div><div class="v11-info" style="margin-top:14px">演示账号均为虚构数据，密码统一为 demo123；账号决定端口、数据范围和可用操作。</div></div></div>'}
  function v141Login(){var newAccount=document.getElementById('v141Account'),oldAccount=document.getElementById('v14Account'),newPassword=document.getElementById('v141Password'),oldPassword=document.getElementById('v14Password'),a=(newAccount||oldAccount||{}).value||'',pw=(newPassword||oldPassword||{}).value||'';if(!a||!pw){notice='请完整填写账号和密码';renderAll();return}if(pw!=='demo123'){notice='密码错误，请使用演示密码 demo123';renderAll();return}var role=a.indexOf('outpatient')===0?'outpatient':a.indexOf('doctor')===0?'doctor':a.indexOf('tech')===0?'lab':a.indexOf('admin')===0?'admin':a.indexOf('patient')===0?'patient':'nurse';A={logged:true,role:role,user:(R[role]||R.nurse).user};S.role=role;if(role==='nurse'){if(oldAccount){legacyLogin();return}var box=document.createElement('div');box.style.display='none';box.innerHTML='<input id="v14Account" value="'+e(a)+'"><input id="v14Password" value="'+e(pw)+'"><select id="v14Hospital"><option selected>云川市第一人民医院</option></select><select id="v14Ward"><option selected>8A 呼吸内科病区</option></select>';document.body.appendChild(box);legacyLogin();box.remove();return}if(role==='patient'){S.patientPage='home';S.patientProfile=false;S.patientDoctor=null;S.patientSlot=null;document.getElementById('side').classList.add('hide');document.getElementById('top').classList.add('hide')}else{S.module=(R[role].nav[0]||['dashboard'])[0];S.sub=((M[role]||{})[S.module]||[['overview','工作区']])[0][0]}notice='登录成功：已进入'+(R[role]||R.nurse).label;renderAll()}
  function v141Logout(){A={logged:false,role:null,user:null};detail=null;notice='';renderAll()}
  function v141Module(m){S.module=m;S.sub=((M[A.role]||{})[m]||[['overview','工作区']])[0][0];detail=null;notice='';renderAll()}
  function v141Sub(s){S.sub=s;detail=null;notice='';renderAll()}
  function pageStats(items){return '<div class="v11-grid3">'+items.map(function(x){return '<button class="v11-stat" onclick="'+(x[3]||'')+'"><small>'+x[0]+'</small><strong>'+x[1]+'</strong><em>'+x[2]+'</em></button>'}).join('')+'</div>'}
  function outpatient(){var m=S.module;if(m==='dashboard')return outpatientDash();if(m==='slots')return outpatientSlots();if(m==='appointments')return outpatientAppointments();if(m==='exceptions')return outpatientExceptions();if(m==='referrals')return outpatientReferrals();if(m==='notify')return outpatientNotify();return outpatientSms()}
  function outpatientDash(){return T('门诊工作台','门诊服务台 · 号源、预约、候诊异常和通知任务',B('新建患者','v141NewPatient()','btn primary'))+pageStats([['今日预约',O.appointments.length,'进入预约患者','v141Module("appointments")'],['今日号源',O.slots.reduce(function(n,x){return n+x.total},0),'查看医生和时段','v141Module("slots")'],['候诊异常',O.appointments.filter(function(x){return x.status==='待签到'}).length,'查看异常原因','v141Module("exceptions")'],['复查/转诊',STORE.followups.length,'进入转诊名单','v141Module("referrals")'],['待通知患者',O.sms.filter(function(x){return x.status==='待发送'}).length+2,'查看电话与短信','v141Module("notify")']])+ '<div class="v11-card"><h2>今日预约患者</h2>'+outpatientAppointmentRows(O.appointments.slice(0,4))+'</div>'}
  function outpatientSlots(){return T('号源管理','按科室、医生、日期和时段维护门诊号源',B('新增号源','v141SlotForm()','btn primary'))+'<div class="v11-card">'+rowTable(['📌号源','科室/医生','日期/时段','总号源','已用','剩余','状态','操作'],O.slots.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.dept+'<br>'+x.doctor+'</td><td>'+x.date+'<br>'+x.time+'</td><td>'+x.total+'</td><td>'+x.used+'</td><td>'+x.remaining+'</td><td>'+b(x.remaining?'可预约':'暂无号源',x.remaining?'good':'info')+'</td><td>'+B('调整号源','v141SlotForm("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141SlotForm(id){var x=O.slots.find(function(z){return z.id===id})||{id:'new',dept:'呼吸内科',doctor:'周明远',date:'2026-10-14',time:'上午 08:00–12:00',total:20,used:0,remaining:20};detail={type:'slot',id:x.id};renderAll()}
  function slotForm(){var x=O.slots.find(function(z){return z.id===detail.id})||{id:'new',dept:'呼吸内科',doctor:'周明远',date:'2026-10-14',time:'上午 08:00–12:00',total:20,used:0,remaining:20};return T(x.id==='new'?'新增号源':'调整号源',x.dept+' · '+x.doctor,B('返回号源列表','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-form"><label>科室 *</label><input id="slotDept" value="'+x.dept+'"><label>医生 *</label><input id="slotDoctor" value="'+x.doctor+'"><label>日期 *</label><input id="slotDate" type="date" value="'+x.date+'"><label>时段 *</label><input id="slotTime" value="'+x.time+'"><label>总号源 *</label><input id="slotTotal" type="number" value="'+x.total+'"><button class="btn primary" onclick="v141SaveSlot(\''+x.id+'\')">保存号源并同步预约页</button></div></div>'}
  function v141SaveSlot(id){var x=O.slots.find(function(z){return z.id===id});var data={id:id==='new'?'SL-'+Date.now():id,dept:document.getElementById('slotDept').value,doctor:document.getElementById('slotDoctor').value,date:document.getElementById('slotDate').value,time:document.getElementById('slotTime').value,total:Number(document.getElementById('slotTotal').value)||0,used:x?x.used:0};data.remaining=Math.max(0,data.total-data.used);if(x)Object.assign(x,data);else O.slots.unshift(data);audit('维护号源','号源',data.id,'号源变更已同步患者预约页');msg('号源已保存，患者端未来 7 天号源已同步')}
  function outpatientAppointmentRows(rows){return rowTable(['📌预约号','患者/电话','医生/科室','预约时间','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'<br>'+x.phone+'</td><td>'+x.doctor+'<br>'+x.dept+'</td><td>'+x.time+'</td><td>'+b(x.status,x.status==='候诊中'?'good':'info')+'</td><td>'+B(x.status==='待签到'?'确认签到':'查看详情',x.status==='待签到'?'v141Checkin("'+x.id+'")':'v141AppointmentDetail("'+x.id+'")','btn primary')+'</td></tr>'}))}
  function outpatientAppointments(){return T('预约患者','今日预约、签到状态和接诊医生对应关系',B('新建患者','v141NewPatient()','btn primary'))+'<div class="v11-card"><div class="filters"><input id="aptQ" placeholder="姓名 / 预约号 / 电话后四位"><button class="btn primary" onclick="v141FilterAppointments()">搜索</button><select><option>全部状态</option><option>待签到</option><option>候诊中</option><option>已完成</option></select></div>'+outpatientAppointmentRows(O.appointments)+'</div>'}
  function v141FilterAppointments(){var q=(document.getElementById('aptQ')||{}).value||'';var rows=O.appointments.filter(function(x){return !q||x.patient.includes(q)||x.id.includes(q)||x.phone.includes(q)});detail={type:'apt-filter',rows:rows};renderAll()}
  function appointmentFiltered(){return detail&&detail.rows?detail.rows:O.appointments}
  function v141Checkin(id){var x=O.appointments.find(function(z){return z.id===id});if(x){x.status='候诊中';audit('确认签到','预约',id,'已签到进入候诊队列');msg('已确认签到，患者进入候诊队列并同步医生今日患者')}}
  function v141AppointmentDetail(id){var x=O.appointments.find(function(z){return z.id===id})||O.appointments[0];detail={type:'apt',id:x.id};renderAll()}
  function aptDetail(){var x=O.appointments.find(function(z){return z.id===detail.id})||O.appointments[0];return T('预约详情',x.patient+' · '+x.id,B('返回预约患者','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-kv"><div><label>患者</label><strong>'+x.patient+'</strong></div><div><label>手机号</label><strong>'+x.phone+'</strong></div><div><label>医生/科室</label><strong>'+x.doctor+' · '+x.dept+'</strong></div><div><label>预约时间</label><strong>'+x.time+'</strong></div><div><label>来源</label><strong>'+x.source+'</strong></div><div><label>当前状态</label><strong>'+b(x.status)+'</strong></div></div><div class="actions">'+(x.status==='待签到'?B('确认签到','v141Checkin("'+x.id+'")','btn primary'):'')+B('发送提醒','v141SendAppointmentSms("'+x.id+'")')+'</div></div>'}
  function v141SendAppointmentSms(id){var x=O.appointments.find(function(z){return z.id===id});O.sms.unshift({id:'SMS-'+Date.now(),patient:x.patient,phone:x.phone,content:'您的'+x.time+'预约已确认，请按时签到',status:'已发送',time:now()});audit('发送短信','预约',id,'已生成通知记录');msg('预约提醒已发送并写入短信通知记录')}
  function outpatientExceptions(){var rows=O.appointments.filter(function(x){return x.status==='待签到'});return T('候诊异常','识别超过预约时间、未签到和改约风险',B('刷新异常','renderAll()'))+'<div class="v11-card">'+rowTable(['📌预约号','患者','预约时间','异常原因','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.time+'</td><td>超过预约时间 30 分钟未签到</td><td>'+b('待处理','warn')+'</td><td>'+B('标记已联系','v141HandleException("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141HandleException(id){var x=O.appointments.find(function(z){return z.id===id});if(x){x.status='已联系';audit('处理候诊异常','预约',id,'已电话联系患者');msg('候诊异常已记录处理结果，状态同步预约患者列表')}}
  function outpatientReferrals(){var rows=STORE.followups;return T('复诊/转诊','住院端复查建议转入门诊号源后形成可追踪预约',B('查看号源','v141Module("slots")'))+'<div class="v11-card">'+rowTable(['📌复查','患者','建议项目','日期','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.advice+'</td><td>'+x.date+'</td><td>'+b(x.status,x.status==='已安排'?'good':'warn')+'</td><td>'+B('转入门诊','v141Transfer("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141Transfer(id){var f=STORE.followups.find(function(x){return x.id===id});if(f){f.status='已转门诊';O.appointments.unshift({id:'APT-'+Date.now(),patient:f.patient,phone:'138****6208',doctor:f.doctor||'周明远',dept:'呼吸内科',time:f.date+' 09:30',status:'已预约',source:'住院转诊'});audit('确认转门诊','复查',id,'已创建门诊预约');msg('复查已转入门诊预约，新增记录已同步患者端')}}
  function outpatientNotify(){var list=[{patient:'孙磊',phone:'138****6205',reason:'检查时间变更',status:'待发送'},{patient:'周文静',phone:'138****6206',reason:'复查号源确认',status:'待发送'}].concat(O.sms.filter(function(x){return x.status==='待发送'}));return T('待通知患者','停诊、改约、检查变更和复查号源的通知闭环',B('批量发送','v141BatchSms()','btn primary'))+'<div class="v11-card">'+rowTable(['患者','电话','通知原因','状态','操作'],list.map(function(x){return '<tr><td>'+x.patient+'</td><td>'+x.phone+'</td><td>'+x.reason+'</td><td>'+b(x.status,x.status==='已发送'?'good':'warn')+'</td><td>'+B('发送短信','v141SendNotify("'+x.patient+'","'+x.phone+'","'+x.reason+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141SendNotify(patient,phone,reason){O.sms.unshift({id:'SMS-'+Date.now(),patient:patient,phone:phone,content:reason,status:'已发送',time:now()});audit('发送短信','通知',patient,reason);msg('短信已发送，送达结果可在短信通知记录查看')}
  function v141BatchSms(){v141SendNotify('待通知患者批次','多位患者','门诊服务台批量通知');}
  function outpatientSms(){return T('短信通知记录','通知对象、模板内容、发送时间和送达状态可追溯')+'<div class="v11-card">'+rowTable(['📌记录','患者/电话','内容','发送时间','状态'],O.sms.concat([{id:'SMS-01',patient:'张莉',phone:'138****6210',content:'门诊号源调整提醒',time:'今日 09:40',status:'已送达'}]).map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'<br>'+x.phone+'</td><td>'+x.content+'</td><td>'+x.time+'</td><td>'+b(x.status,'good')+'</td></tr>'}))+'</div>'}
  function v141NewPatient(){detail={type:'newpatient'};renderAll()}
  function newPatient(){return T('新建患者','门诊服务台新增流程，保存后进入预约患者列表',B('返回门诊工作台','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-form"><label>姓名 *</label><input id="npName"><label>性别 *</label><select id="npGender"><option>女</option><option>男</option></select><label>手机号 *</label><input id="npPhone"><label>就诊科室 *</label><select id="npDept"><option>呼吸内科</option><option>全科医学科</option></select><button class="btn primary" onclick="v141SavePatient()">保存患者并创建预约候选</button></div></div>'}
  function v141SavePatient(){var n=(document.getElementById('npName')||{}).value||'',ph=(document.getElementById('npPhone')||{}).value||'';if(!n||!ph){msg('请填写姓名和手机号');return}O.appointments.unshift({id:'APT-'+Date.now(),patient:n,phone:ph,doctor:'待分配',dept:document.getElementById('npDept').value,time:'待安排',status:'待签到',source:'服务台新建'});audit('新建患者','门诊患者',n,'已进入预约患者列表');msg('患者已保存并进入预约患者列表，可继续完成号源安排')}
  function doctor(){var m=S.module;if(m==='dashboard')return doctorDash();if(m==='today')return doctorToday();if(m==='reports')return doctorReports();if(m==='critical')return doctorCritical();if(m==='plans')return doctorPlans();if(m==='orders')return doctorOrders();if(m==='online')return onlineService();if(m==='followup')return doctorFollowup();if(m==='messages')return doctorMessages();return doctorAudit()}
  function onlineService(){return T('线上服务工作台','既有线上医生/护士项目的消息承接、回复和宣教审核',B('刷新消息','renderAll()'))+'<div class="v11-card">'+rowTable(['📌留言','患者','类型/内容','状态','操作'],STORE.messages.slice(0,6).map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.type+'<br>'+x.text+'</td><td>'+b(x.status,x.status==='未读'?'warn':'info')+'</td><td>'+B('接单回复','v141OnlineReply("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div><div class="v11-card"><h2>AI 宣教审核</h2><div class="v11-info">审核后才推送患者端；内容仅限健康宣教、检查准备和复诊提醒。</div>'+B('审核当前草稿','v141ApproveEducation()','btn primary')+'</div>'}
  function v141OnlineReply(id){audit('线上回复','患者留言',id,'进入既有线上医生/护士服务回复队列');msg('已接单，患者端将显示待回复状态')} window.v141OnlineReply=v141OnlineReply;
  function v141ApproveEducation(){audit('审核健康宣教','AI宣教','EDU-'+Date.now(),'已人工确认依据和来源时间');msg('健康宣教草稿已审核，可推送患者端')} window.v141ApproveEducation=v141ApproveEducation;
  function doctorDash(){return T('医生工作台','周明远医生 · 本人接诊范围 · 今日临床任务',B('进入危急值','v141Module("critical")','btn danger'))+pageStats([['今日患者',STORE.patients.length,'进入接诊队列','v141Module("today")'],['报告待办',STORE.reports.filter(function(x){return !x.doctorViewedAt}).length,'查看报告正文','v141Module("reports")'],['危急值待确认',STORE.criticals.filter(function(x){return !x.doctorAt}).length,'进入处置闭环','v141Module("critical")'],['待完成方案',STORE.patients.filter(function(x){return ['报告待查看','危急值待确认'].includes(x.stage)}).length,'填写诊疗方案','v141Module("plans")']])+ '<div class="v11-card"><h2>今日患者</h2>'+doctorPatientRows(STORE.patients.slice(0,5))+'</div>'}
  function doctorPatientRows(rows){return rowTable(['📌患者/住院号','疾病/床位','当前阶段','报告','操作'],rows.map(function(x){return '<tr><td>'+x.name+'<br>'+x.id+'</td><td>'+x.disease+'<br>'+x.bed+'</td><td>'+b(x.stage,x.stage==='危急值待确认'?'bad':'info')+'</td><td>'+x.report+'</td><td>'+B('查看患者','v141DoctorPatient("'+x.id+'")','btn primary')+'</td></tr>'}))}
  function doctorToday(){var rows=STORE.patients;return T('今日患者','本人接诊范围 · 候诊、已接诊、检查中、完成',B('刷新队列','renderAll()'))+'<div class="v11-card"><div class="filters"><input id="docQ" placeholder="患者姓名 / 住院号"><button class="btn primary" onclick="v141DoctorSearch()">搜索</button></div>'+doctorPatientRows(rows)+'</div>'}
  function v141DoctorSearch(){var q=(document.getElementById('docQ')||{}).value||'';detail={type:'doctor-search',rows:STORE.patients.filter(function(x){return !q||x.name.includes(q)||x.id.includes(q)})};renderAll()}
