  function doctorPatientDetail(){var x=p(detail.id);return T('患者诊疗详情',x.name+' · '+x.id+' · '+x.disease,B('返回今日患者','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-kv"><div><label>性别/年龄</label><strong>'+x.gender+' · '+x.age+'岁</strong></div><div><label>床位</label><strong>'+x.bed+'</strong></div><div><label>检查项目</label><strong>'+x.exam+'</strong></div><div><label>报告状态</label><strong>'+x.report+'</strong></div><div><label>流程状态</label><strong>'+x.stage+'</strong></div><div><label>下一步</label><strong>'+x.next+'</strong></div></div></div><div class="v11-card"><h2>诊疗时间轴</h2><div class="timeline"><div class="step done">预约/接诊</div><div class="step done">检查预约</div><div class="step '+(x.stage==='检查中'?'cur':'done')+'">检查中</div><div class="step '+(x.report==='待出报告'?'cur':'done')+'">报告生成</div><div class="step '+(x.stage==='危急值待确认'?'cur':'')+'">医生确认</div><div class="step">复查安排</div></div></div><div class="actions">'+B('查看报告','v141OpenDoctorReport("'+x.id+'")','btn primary')+B('填写诊疗方案','v141DoctorPlan("'+x.id+'")','btn primary')+'</div>'}
  function doctorReports(){var rows=STORE.reports;return T('报告待办','报告正文、参考区间、异常指标和医生查看时间',B('查看危急值','v141Module("critical")','btn danger'))+'<div class="v11-card">'+rowTable(['📌报告','患者','检查项目','出报告时间','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'<br>'+x.patientId+'</td><td>'+x.project+'</td><td>'+x.issuedAt+'</td><td>'+b(x.doctorViewedAt?'已查看':'待查看',x.doctorViewedAt?'good':'warn')+'</td><td>'+B('查看报告','v141OpenDoctorReport("'+x.patientId+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141OpenDoctorReport(id){detail={type:'doctor-report',id:id};renderAll()}
  function doctorReportDetail(){var x=p(detail.id),r=STORE.reports.find(function(z){return z.patientId===detail.id})||null;return T('报告详情',x.name+' · '+x.exam,B('返回报告待办','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-kv"><div><label>患者</label><strong>'+x.name+' · '+x.id+'</strong></div><div><label>检查项目</label><strong>'+r.project+'</strong></div><div><label>结果</label><strong>'+r.result+'</strong></div><div><label>参考区间</label><strong>'+r.reference+'</strong></div><div><label>出报告时间</label><strong>'+r.issuedAt+'</strong></div><div><label>当前状态</label><strong>'+r.status+'</strong></div></div></div><div class="v11-card"><h2>医生处理</h2><div class="v11-form"><label>临床判断 *</label><textarea id="docJudgement" rows="3" placeholder="结合症状、检查和报告填写临床判断"></textarea><button class="btn primary" onclick="v141ConfirmDoctorReport(\''+detail.id+'\')">确认已查看并生成方案任务</button></div></div>'}
  function v141ConfirmDoctorReport(id){var r=STORE.reports.find(function(x){return x.patientId===id});if(r){r.doctorViewedAt=now();if(r.status==='待医生确认')r.status='医生已确认';audit('查看报告','报告',r.id,'医生已填写临床判断');msg('报告已标记为医生已查看，诊疗方案任务已生成')}}
  function doctorCritical(){return T('危急值待确认','只展示本人接诊范围内的异常值，需记录确认、处置和完成时间')+'<div class="v11-card">'+rowTable(['📌事件','患者','异常指标','发现/护士响应','状态','操作'],STORE.criticals.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'<br>'+x.patientId+'</td><td>'+x.project+'<br><b style="color:var(--bad)">'+x.value+'</b></td><td>'+x.foundAt+'<br>'+(x.nurseAt||'待响应')+'</td><td>'+b(x.doctorAt?'已确认':'待确认',x.doctorAt?'good':'bad')+'</td><td>'+B('处理危急值','v141DoctorCritical("'+x.patientId+'")','btn danger')+'</td></tr>'}))+'</div>'}
  function v141DoctorCritical(id){detail={type:'doctor-critical',id:id};renderAll()}
  function doctorCriticalDetail(){var c=STORE.criticals.find(function(x){return x.patientId===detail.id})||STORE.criticals[0],x=p(detail.id);return T('危急值处置',x.name+' · '+c.project+' · '+c.value,B('返回危急值列表','v141CloseDetail()'))+'<div class="v11-alert"><b>'+c.value+'</b> · 参考区间 '+c.reference+' · 发现 '+c.foundAt+' · 护士响应 '+(c.nurseAt||'待确认')+'</div><div class="v11-card"><div class="v11-form"><label>医生工号 *</label><input id="docId" value="DOC-001"><label>事件级别 *</label><select id="docSeverity"><option>普通危急值</option><option>病情紧急</option><option>抢救中</option></select><label>处置意见 *</label><textarea id="docCriticalNote" rows="4" placeholder="记录复核结果、处置和后续监护要求"></textarea><button class="btn danger" onclick="v141ConfirmDoctorCritical(\''+c.patientId+'\')">确认危急值并完成处置记录</button></div><div class="v11-info">“病情紧急”和“抢救中”只能由医生或授权责任人确认，系统不会根据单项检验结果自动推断。</div></div><div class="v11-card"><h2>响应时间线</h2><div class="v11-kv"><div><label>发现</label><strong>'+c.foundAt+'</strong></div><div><label>护士响应</label><strong>'+(c.nurseAt||'待确认')+'</strong></div><div><label>医生响应</label><strong>'+(c.doctorAt||'待确认')+'</strong></div><div><label>处置完成</label><strong>'+(c.doneAt||'待完成')+'</strong></div></div></div>'}
  function v141ConfirmDoctorCritical(id){var c=STORE.criticals.find(function(x){return x.patientId===id}),x=p(id),note=(document.getElementById('docCriticalNote')||{}).value||'',severity=(document.getElementById('docSeverity')||{}).value||'普通危急值';if(!note){msg('请填写处置意见后再完成危急值闭环');return}if(c){c.doctorAt=now();c.doneAt=now();c.status='处置完成';c.severity=severity;c.note=note;x.stage='已完成';x.next='按方案观察并安排复查';audit('处置危急值','危急值',c.id,severity+'；'+note);msg('危急值已完成医生确认和处置记录，护士端与患者进度已同步')}}
  function doctorPlans(){var rows=STORE.patients.filter(function(x){var r=STORE.reports.find(function(z){return z.patientId===x.id});return !x.plan&&r&&r.doctorViewedAt});return T('待完成方案','仅显示医生已查看报告且尚未完成方案的患者',B('返回医生工作台','v141Module("dashboard")'))+'<div class="v11-card">'+rowTable(['📌患者','报告/阶段','待完成内容','操作'],rows.map(function(x){return '<tr><td>'+x.name+'<br>'+x.id+'</td><td>'+x.report+'<br>'+x.stage+'</td><td>治疗方案、患者教育、复查安排</td><td>'+B('填写方案','v141DoctorPlan("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div><div class="v11-info">报告未发布或医生未完成查看回执的患者，不进入方案任务列表。</div>'}
  function v141DoctorPlan(id){detail={type:'plan',id:id};renderAll()}
  function planForm(){var x=p(detail.id),r=STORE.reports.find(function(z){return z.patientId===x.id});if(!r||!r.doctorViewedAt)return T('诊疗方案前置门禁',x.name+' · '+x.disease,B('返回医生工作台','v141Module("plans")'))+'<div class="v11-card"><div class="v11-alert">必须先满足“医技已发布 + 医生已查看报告”，才能填写诊疗方案。</div><div class="v11-kv"><div><label>报告状态</label><strong>'+(r?r.status:'未找到当前患者报告')+'</strong></div><div><label>医生查看回执</label><strong>'+(r&&r.doctorViewedAt||'未查看')+'</strong></div></div></div>';return T('填写诊疗方案',x.name+' · '+x.disease,B('返回待完成方案','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-form"><label>治疗方案 *</label><textarea id="planText" rows="4" placeholder="填写药物、观察和处置计划"></textarea><label>患者教育</label><textarea id="eduText" rows="3" placeholder="填写患者需要理解的注意事项"></textarea><label>复查日期</label><input id="planDate" type="date" value="2026-10-20"><button class="btn primary" onclick="v141SavePlan(\''+x.id+'\')">保存方案并同步复查任务</button></div></div>'}
  function v141SavePlan(id){var x=p(id),r=STORE.reports.find(function(z){return z.patientId===id});if(!r||!r.doctorViewedAt){msg('必须先查看已发布报告，方案未保存');return}x.plan=(document.getElementById('planText')||{}).value||'已完成诊疗方案';x.education=(document.getElementById('eduText')||{}).value||'已完成患者教育';x.stage='复查待安排';x.next='患者复查预约待安排';var f=STORE.followups.find(function(z){return z.patientId===id});if(f)f.status='待安排';else STORE.followups.unshift({id:'FU-'+Date.now(),patientId:id,patient:x.name,doctor:x.doctor,advice:'复查'+x.exam,date:(document.getElementById('planDate')||{}).value||'2026-10-20',status:'待安排',result:'—'});audit('保存诊疗方案','患者',id,'方案、教育和复查任务已同步');msg('诊疗方案已保存，复查任务已同步患者端和住院护士端')}
  function doctorOrders(){return T('检查申请','医生本人接诊范围 · 填写检查项目、目的和期望时间',B('新增检查申请','v141DoctorOrderForm()','btn primary'))+'<div class="v11-card">'+rowTable(['📌申请','患者','检查项目/目的','时间地点','状态','操作'],STORE.exams.filter(function(x){return p(x.patientId).doctor==='周明远'}).map(function(x){return '<tr><td>'+x.id+'</td><td>'+p(x.patientId).name+'<br>'+p(x.patientId).id+'</td><td>'+x.project+'<br>'+(x.reason||'临床评估')+'</td><td>'+x.appointment+'<br>'+x.location+'</td><td>'+b(x.status,x.status==='已完成'?'good':'info')+'</td><td>'+B('查看患者','v141DoctorPatient("'+x.patientId+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141DoctorOrderForm(){detail={type:'doctor-order'};renderAll()}
  function doctorOrderForm(){return T('新增检查申请','申请提交后进入住院护士检查协调队列',B('返回检查申请','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-form"><label>患者 *</label><select id="orderPatient">'+STORE.patients.map(function(x){return '<option value="'+x.id+'">'+x.name+' · '+x.id+' · '+x.bed+'</option>'}).join('')+'</select><label>检查项目 *</label><select id="orderProject"><option>胸部 CT</option><option>动脉血气分析</option><option>肺功能检查</option><option>痰培养</option></select><label>临床目的 *</label><textarea id="orderReason" rows="3" placeholder="填写检查目的和关注问题"></textarea><label>期望日期 *</label><input id="orderDate" type="date" value="2026-10-14"><label>优先级</label><select id="orderPriority"><option>常规</option><option>加急</option></select><button class="btn primary" onclick="v141SubmitDoctorOrder()">提交检查申请并通知护士</button></div></div>'}
  function v141SubmitDoctorOrder(){var id=document.getElementById('orderPatient').value,project=document.getElementById('orderProject').value,reason=(document.getElementById('orderReason')||{}).value||'';if(!reason){msg('请填写临床目的，提交前需保留申请依据');return}var q=p(id),x={id:'EX-'+Date.now(),patientId:id,patient:q.name,dept:'8A 呼吸内科',project:project,location:'待护士协调',appointment:'待预约',prep:'待护士核对准备事项',status:'待预约',expected:'待协调',operator:'周明远医生',changedAt:now(),reason:reason,priority:document.getElementById('orderPriority').value};STORE.exams.unshift(x);q.stage='待检查';q.exam=project;q.next='护士协调检查预约';STORE.messages.unshift({id:'MSG-'+Date.now(),type:'prep',patient:q.name,patientId:id,text:'医生已提交'+project+'检查申请，待护士协调',deadline:'今日',status:'未读'});audit('提交检查申请','检查订单',x.id,reason);msg('检查申请已提交，护士端检查协调队列已生成任务')}
  function doctorFollowup(){return T('复诊随访','查看医生建议的复查日期、项目和结果回传',B('进入待完成方案','v141Module("plans")'))+'<div class="v11-card">'+rowTable(['📌复查','患者','建议项目','日期','状态','操作'],STORE.followups.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.advice+'</td><td>'+x.date+'</td><td>'+b(x.status,x.status==='已安排'?'good':'warn')+'</td><td>'+B('查看患者','v141DoctorPatient("'+x.patientId+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function doctorMessages(){var rows=STORE.messages;return T('消息中心','危急值、报告和复查任务统一聚合，处理动作回到专门页面')+'<div class="v11-card">'+rowTable(['📌消息','患者','内容','截止时间','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.text+'</td><td>'+x.deadline+'</td><td>'+b(x.status,x.status==='未读'?'warn':'info')+'</td><td>'+B('定位处理','v141LocateMessage("'+x.type+'","'+x.patientId+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function v141LocateMessage(type,id){if(type==='critical'){v141DoctorCritical(id);return}if(type==='report'){v141OpenDoctorReport(id);return}v141DoctorPatient(id)}
  function doctorAudit(){var rows=STORE.audit.length?STORE.audit:[{id:'AUD-01',action:'查看报告',entity:'报告',entityId:'RP-260801',operator:'周明远医生',time:'今日 10:12',note:'演示记录'}];return T('审计记录','医生本人查看、确认、保存方案和危急值处置均可追溯',B('导出审计','v141ExportAudit()','btn primary'))+'<div class="v11-card">'+rowTable(['📌记录','动作','对象','操作人','时间','备注'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.action+'</td><td>'+x.entity+' · '+x.entityId+'</td><td>'+x.operator+'</td><td>'+x.time+'</td><td>'+x.note+'</td></tr>'}))+'</div>'}
  function v141ExportAudit(){var csv='记录,动作,对象,操作人,时间\n'+STORE.audit.map(function(x){return [x.id,x.action,x.entity+' '+x.entityId,x.operator,x.time].join(',')}).join('\n'),a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);a.download='医生审计记录.csv';a.click();msg('医生审计 CSV 已生成并下载')}
  function lab(){var m=S.module;if(m==='dashboard')return labDash();if(m==='execution')return labExecution();if(m==='sync')return labSync();if(m==='efficiency')return labEfficiency();return labList(m)}
  function labEfficiency(){return T('检验科工效分析','只用于流程优化；不自动生成个人绩效或处罚结论',B('标记数据复核','v141EfficiencyReview()','btn primary'))+'<div class="v11-card">'+rowTable(['📌人员','接待患者数','完成检查数','平均执行时长','平均报告时长','数据质量'],[['李医技','18','16','20 分钟','15 分钟','完整'],['王技师','14','13','24 分钟','18 分钟','完整'],['赵技师','—','—','—','—','事件缺失']].map(function(x){return '<tr>'+x.map(function(v){return '<td>'+v+'</td>'}).join('')+'</tr>'}))+'</div><div class="v11-info">数据按时间范围、项目和事件完整性计算；缺失事件不参与均值，不直接用于人员排名。</div>'}
  function v141EfficiencyReview(){audit('标记工效数据复核','检验科工效','EFF-'+Date.now(),'发现事件缺失，进入人工复核');msg('已创建数据复核任务，未修改原始检查事件')} window.v141EfficiencyReview=v141EfficiencyReview;
  function labDash(){return T('检验工作台','检验科/医技端 · 从预约检验到检查执行、报告生成和同步',B('进入执行队列','v141Module("execution")','btn primary'))+pageStats([['今日预约检验',24,'患者、科室、检查项目','v141Module("today")'],['已做检查',18,'查看已完成检查','v141Module("done")'],['未做检查',6,'查看未执行/缺席','v141Module("undone")'],['待出报告',STORE.exams.filter(function(x){return x.status==='检查中'}).length,'生成报告','v141Module("pending")'],['已出报告',STORE.reports.length,'查看报告同步','v141Module("sync")']])+'<div class="v11-card"><h2>医技队列说明</h2><div class="v11-info">预约检验、接收执行、已做检查、未做检查、待出报告、报告生成、已出报告和报告同步分别承载独立节点。</div></div>'}
  function labExecution(){var xs=STORE.exams.filter(function(x){return x.status==='检查中'});return T('接收/执行检查','已接收患者或样本的执行队列；完成后进入报告生成',B('返回今日预约检验','v141Module("today")'))+'<div class="v11-card">'+labRows(xs,function(x){return B('确认检查完成','v141LabComplete("'+x.id+'")','btn primary')})+'</div>'}
  function v141LabComplete(id){var x=STORE.exams.find(function(z){return z.id===id});if(x){x.status='已完成';x.prep='检查完成，待生成报告';x.completedAt=now();p(x.patientId).stage='检查中';audit('完成检查执行','检查订单',id,'进入待出报告队列');msg('检查已完成，已进入待出报告队列')}}
  function labSync(){var rows=STORE.reports;return T('报告同步','报告发布后同步护士、医生和患者端的独立回执',B('刷新同步状态','renderAll()'))+'<div class="v11-card">'+rowTable(['📌报告','患者','发布时间','护士端','医生端','患者端','操作'],rows.map(function(x){var sync=x.sync||{nurse:x.nurseViewedAt?'已接收':'待接收',doctor:x.doctorViewedAt?'已接收':'待接收',patient:x.patientViewedAt?'已接收':'待接收'},ex=STORE.exams.find(function(e){return e.patientId===x.patientId});return '<tr><td>'+x.id+'</td><td>'+x.patient+'<br>'+x.patientId+'</td><td>'+x.issuedAt+'</td><td>'+b(sync.nurse,sync.nurse==='已接收'?'good':'warn')+'</td><td>'+b(sync.doctor,sync.doctor==='已接收'?'good':'warn')+'</td><td>'+b(sync.patient,sync.patient==='已接收'?'good':'warn')+'</td><td>'+B('查看报告','v141LabResult("'+(ex?ex.id:'')+'")','btn primary')+'</td></tr>'}))+'</div>'}
  function labRows(xs,action){return rowTable(['📌订单','患者/科室','检查项目','预约时间','状态','操作'],xs.map(function(x){var q=p(x.patientId);return '<tr><td>'+x.id+'</td><td>'+q.name+'<br>'+x.dept+'</td><td>'+x.project+'</td><td>'+x.appointment+'</td><td>'+b(x.status,x.status==='检查中'?'warn':x.status==='已完成'?'good':'info')+'</td><td>'+action(x,q)+'</td></tr>'}))}
  function labList(m){var xs=STORE.exams.filter(function(x){var rr=STORE.reports.find(function(r){return r.patientId===x.patientId});if(m==='today')return ['待预约','已预约','待准备','检查中'].includes(x.status);if(m==='done')return x.status==='已完成';if(m==='undone')return x.status==='待预约'||x.status==='未执行';if(m==='pending')return x.status==='已完成'&&(!rr||rr.status==='待出结果'||rr.status==='待护士查看');return x.status==='已完成'});var label={today:'今日预约检验',done:'已做检查',undone:'未做检查',pending:'待出报告',sent:'已出报告'}[m];return T(label,'只展示检验科本科室队列 · 当前数量 '+xs.length,(m==='pending'?B('刷新队列','renderAll()'):''))+'<div class="v11-card">'+labRows(xs,function(x,q){if(m==='today')return B('接收患者','v141LabReceive("'+x.id+'")','btn primary');if(m==='done')return B('查看结果','v141LabResult("'+x.id+'")','btn primary');if(m==='undone')return B('标记未执行','v141LabSkip("'+x.id+'")','btn');if(m==='pending')return B('生成报告','v141LabResult("'+x.id+'")','btn primary');return B('查看报告','v141LabResult("'+x.id+'")','btn primary')})+'</div>'}
  function v141LabReceive(id){var x=STORE.exams.find(function(z){return z.id===id});if(x){x.status='检查中';x.prep='样本/患者已接收';p(x.patientId).stage='检查中';audit('接收检查','检查订单',id,'医技端开始执行');msg('检查订单已进入执行中，住院护士和医生端状态已同步')}}
  function v141LabSkip(id){var x=STORE.exams.find(function(z){return z.id===id});if(x){x.status='未执行';x.prep='患者未到/未执行';audit('标记未执行','检查订单',id,'保留未执行原因');msg('检查已标记为未执行，记录保留在医技队列')}}
  function v141LabResult(id){detail={type:'lab-result',id:id};renderAll()}
  function labResult(){var x=STORE.exams.find(function(z){return z.id===detail.id}),q=p(x.patientId),r=STORE.reports.find(function(z){return z.patientId===q.id})||{};return T('生成检查报告',q.name+' · '+x.project,B('返回医技队列','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-kv"><div><label>患者</label><strong>'+q.name+' · '+q.id+'</strong></div><div><label>检查项目</label><strong>'+x.project+'</strong></div><div><label>检查地点</label><strong>'+x.location+'</strong></div><div><label>当前状态</label><strong>'+x.status+'</strong></div><div><label>审核状态</label><strong>'+(r.reviewedAt?'已审核':'待审核')+'</strong></div><div><label>发布状态</label><strong>'+(r.status||'待发布')+'</strong></div></div><div class="v11-form"><label>检查结果 *</label><textarea id="labResultText" rows="4" placeholder="填写真实演示数据：结果、参考区间和异常判断">'+(r.draftResult||r.result||'')+'</textarea><label>参考区间</label><input id="labRef" value="'+(r.reference||'详见项目参考区间')+'"><label>危急值判定</label><select id="labCritical"><option>无</option><option>疑似危急值</option><option>危急值</option></select><div class="actions">'+B('保存结果','v141SaveLabResult(\''+x.id+'\')')+B('审核结果','v141ReviewLabResult(\''+x.id+'\')')+B('发布报告并同步回执','v141PublishReport(\''+x.id+'\')','btn primary')+'</div></div><div class="v11-info">发布前必须完成结果录入和审核；发布后护士、医生、患者端分别形成同步回执。</div></div>'}
  function v141SaveLabResult(id){var x=STORE.exams.find(function(z){return z.id===id}),q=p(x.patientId),r=STORE.reports.find(function(z){return z.patientId===q.id})||{id:'RP-'+Date.now(),patientId:q.id,patient:q.name,project:x.project,doctor:'李医技'};r.draftResult=(document.getElementById('labResultText')||{}).value||'';r.reference=(document.getElementById('labRef')||{}).value||'详见报告';r.resultStatus='结果已录入';if(!STORE.reports.includes(r))STORE.reports.unshift(r);audit('录入报告结果','报告',r.id,'结果、参考区间和危急值判定已保存');msg('报告结果已保存，仍需审核后才能发布')}
  function v141ReviewLabResult(id){var x=STORE.exams.find(function(z){return z.id===id}),q=p(x.patientId),r=STORE.reports.find(function(z){return z.patientId===q.id});if(!r||!r.draftResult){msg('请先保存报告结果再审核');return}r.reviewedAt=now();r.status='已审核';audit('审核报告','报告',r.id,'医技审核通过，等待发布');msg('报告已审核，可以发布并生成同步回执')}
  function v141PublishReport(id){var x=STORE.exams.find(function(z){return z.id===id}),q=p(x.patientId),r=STORE.reports.find(function(z){return z.patientId===q.id});if(!r||!r.reviewedAt){msg('发布已阻断：请先完成结果录入和审核');return}var text=r.draftResult||'检查结果已生成，需结合临床判断',ref=r.reference||'详见报告';x.status='已完成';x.prep='检查完成，报告已发布';q.stage='报告待查看';q.report='已出结果待护士查看';q.next='护士查看报告并通知医生';Object.assign(r,{result:text,reference:ref,status:'待护士查看',issuedAt:now(),publishedAt:now(),nurseViewedAt:null,doctorViewedAt:null,patientViewedAt:null,sync:{nurse:'待接收',doctor:'待接收',patient:'待接收'}});STORE.messages.unshift({id:'MSG-'+Date.now(),type:'report',patient:q.name,patientId:q.id,text:'医技已发布'+x.project+'报告，待护士和医生查看',deadline:'今日',status:'未读'});audit('发布报告','报告',x.id,'报告已发布并生成护士、医生、患者同步回执');msg('报告已发布，护士、医生和患者端同步回执已生成')}
  function admin(){var m=S.module;if(m==='overview')return adminOverview();if(m==='trends')return adminTrends();if(m==='efficiency')return adminEfficiency();if(m==='analysis')return adminAnalysis();if(m==='quality')return adminQuality();if(m==='audit')return adminAudit();if(m==='voice')return adminVoice();if(m==='ops')return adminOps();return adminComplaints()}
  function adminVoice(){return T('患者反馈分析','留言与投诉分离聚合，关键词不展示患者完整原文',B('生成关键词','v141Keywords()','btn primary'))+'<div class="v11-two"><div class="v11-card"><h2>服务留言关键词</h2><div class="v11-info">报告提醒、检查准备、线上回复、预约咨询</div></div><div class="v11-card"><h2>投诉关键词</h2><div class="v11-info">等待时间长、预约困难、号源不足、报告超时</div></div></div>'}
  function adminOps(){return T('流程优化','关联检验科工效快照、超时事件和改进任务',B('查看工效分析','v141Module("efficiency")','btn primary'))+'<div class="v11-card"><h2>待优化瓶颈</h2>'+rowTable(['📌环节','证据','建议动作','状态'],['<tr><td>检查等待</td><td>平均 24 分钟，P90 41 分钟</td><td>调整高峰时段号源</td><td>'+b('待确认','warn')+'</td></tr>','<tr><td>报告发布</td><td>2 个订单缺失完成事件</td><td>补齐设备事件回传</td><td>'+b('待复核','warn')+'</td></tr>'])+'</div>'}
  function adminPeriodData(){var k=S.adminPeriod||'today';return k==='week'?{label:'本周',visits:'8,942',wait:'28 分钟',report:'86 分钟',critical:'8 分钟',data:[72,96,110,124,118,132,146],labels:['一','二','三','四','五','六','日']} : k==='month'?{label:'本月',visits:'36,420',wait:'29 分钟',report:'88 分钟',critical:'8 分钟',data:[420,510,480,620,590],labels:['第1周','第2周','第3周','第4周','第5周']} : k==='quarter'?{label:'本季度',visits:'108,620',wait:'31 分钟',report:'91 分钟',critical:'9 分钟',data:[1200,1480,1390],labels:['7月','8月','9月']} : k==='year'?{label:'本年度',visits:'428,900',wait:'33 分钟',report:'94 分钟',critical:'9 分钟',data:[32000,36000,41000,44000,48000],labels:['2026Q1','Q2','Q3','Q4','累计']} : {label:'今日',visits:'1,286',wait:'26 分钟',report:'83 分钟',critical:'7 分钟',data:[32,46,52,44,61,58,70],labels:['08','10','12','14','16','18','20']}}
  function adminPeriodSelect(){return '<div class="filters"><select onchange="v141SetAdminPeriod(this.value)"><option value="today" '+((S.adminPeriod||'today')==='today'?'selected':'')+'>今日</option><option value="week" '+(S.adminPeriod==='week'?'selected':'')+'>本周</option><option value="month" '+(S.adminPeriod==='month'?'selected':'')+'>本月</option><option value="quarter" '+(S.adminPeriod==='quarter'?'selected':'')+'>本季度</option><option value="year" '+(S.adminPeriod==='year'?'selected':'')+'>本年度</option></select><span class="sub">当前统计切片：'+adminPeriodData().label+'</span></div>'}
