  function adminOverview(){var d=adminPeriodData();return T('管理驾驶舱','全院聚合数据 · '+d.label+'运营总览',B('导出运营报表','v141ExportAdmin()','btn primary'))+adminPeriodSelect()+pageStats([['就诊人数',d.visits,'当前统计切片','v141Module("trends")'],['平均候诊',d.wait,'目标 ≤ 30 分钟','v141Module("efficiency")'],['报告时效',d.report,'目标 ≤ 90 分钟','v141Module("efficiency")'],['危急值响应',d.critical,'目标 ≤ 10 分钟','v141Module("quality")'],['待处理投诉',O.complaints.filter(function(x){return x.status!=='已关闭'}).length,'进入投诉闭环','v141Module("complaints")']])+'<div class="v11-two"><div class="v11-card"><h2>'+d.label+'就诊量</h2>'+scaledChart(d.data,d.labels,'人')+'</div><div class="v11-card"><h2>管理动作</h2>'+B('查看流程效率','v141Module("efficiency")','btn primary')+B('查看质量事件','v141Module("quality")')+B('查看投诉分析','v141Module("complaints")')+'</div></div>'}
  function adminTrends(){var d=adminPeriodData();return T('就诊趋势','按日、周、月、季度、年度切换全院就诊人数变化',B('导出趋势','v141ExportAdmin()','btn primary'))+adminPeriodSelect()+'<div class="filters"><select><option>全院</option><option>呼吸内科</option><option>影像科</option></select><button class="btn primary" onclick="v141ApplyTrend()">应用筛选</button></div><div class="v11-card"><h2>'+d.label+'人数变化</h2>'+scaledChart(d.data,d.labels,'人')+'</div>'}
  function v141ApplyTrend(){msg('趋势筛选已应用，图表已更新')}
  function adminEfficiency(){return T('流程效率','挂号至接诊、检查耗时、报告时效和危急值响应分开分析',B('导出时效分析','v141ExportAdmin()','btn primary'))+'<div class="v11-card">'+rowTable(['📌流程节点','本周期均值','目标','达标率','趋势'],['<tr><td>挂号→接诊</td><td>26 分钟</td><td>≤30 分钟</td><td>'+b('94%','good')+'</td><td>↓ 4 分钟</td></tr>','<tr><td>检查执行耗时</td><td>42 分钟</td><td>≤60 分钟</td><td>'+b('91%','good')+'</td><td>↓ 8 分钟</td></tr>','<tr><td>检查→报告</td><td>83 分钟</td><td>≤90 分钟</td><td>'+b('88%','warn')+'</td><td>↑ 3 分钟</td></tr>','<tr><td>危急值响应</td><td>7 分钟</td><td>≤10 分钟</td><td>'+b('96%','good')+'</td><td>稳定</td></tr>'])+'</div>'}
  function adminAnalysis(){return T('检查/报告分析','检查量、报告完成率和报告时效采用不同指标集',B('导出分析','v141ExportAdmin()','btn primary'))+'<div class="v11-two"><div class="v11-card"><h2>检查量</h2>'+scaledChart([18,14,9,6],['CT','肺功','血气','培养'],'例')+'</div><div class="v11-card"><h2>报告时效</h2>'+scaledChart([72,80,83,76,91],['影像科','检验科','内镜','超声','病理'],'分钟')+'</div></div>'}
  function adminQuality(){return T('质量分析','报告质量、危急值响应和闭环率的管理视图',B('查看流程效率','v141Module("efficiency")','btn primary'))+'<div class="v11-card">'+rowTable(['📌质量指标','当前值','目标','状态','下钻'],['<tr><td>报告按时完成率</td><td>94%</td><td>≥90%</td><td>'+b('达标','good')+'</td><td>'+B('查看报告质量','v141Module("analysis")')+'</td></tr>','<tr><td>危急值响应完成率</td><td>96%</td><td>≥95%</td><td>'+b('达标','good')+'</td><td>'+B('查看响应事件','v141Module("efficiency")')+'</td></tr>','<tr><td>患者通知送达率</td><td>98.6%</td><td>≥98%</td><td>'+b('达标','good')+'</td><td>'+B('查看通知审计','v141Module("audit")')+'</td></tr>'])+'</div>'}
  function adminAudit(){var rows=STORE.audit.length?STORE.audit:[{id:'AUD-01',action:'示例审计记录',entity:'系统',entityId:'—',operator:'陈运营',time:now(),note:'当前为演示数据'}];return T('权限与审计','管理端只读查看操作审计、通知记录和数据范围，不执行一线临床操作',B('导出审计','v141ExportAdmin()','btn primary'))+'<div class="v11-card">'+rowTable(['📌记录','动作','对象','操作人','时间','备注'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.action+'</td><td>'+x.entity+' · '+x.entityId+'</td><td>'+x.operator+'</td><td>'+x.time+'</td><td>'+x.note+'</td></tr>'}))+'</div>'}
  function adminComplaints(){return T('投诉分析','投诉记录、关键词和改进建议形成处理闭环',B('生成关键词总结','v141Keywords()','btn primary'))+'<div class="v11-card">'+rowTable(['📌投诉','患者','分类/内容','时间','状态','操作'],O.complaints.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.patient+'</td><td>'+x.category+'<br>'+x.text+'</td><td>'+x.time+'</td><td>'+b(x.status,x.status==='已关闭'?'good':'warn')+'</td><td>'+B(x.status==='待受理'?'受理投诉':'关闭投诉','v141ComplaintAction("'+x.id+'")','btn primary')+'</td></tr>'}))+'</div><div class="v11-card"><h2>当前关键词</h2><div class="v11-info">等待时间长 · 预约困难 · 号源不足 · 报告提醒延迟</div></div>'}
  function v141ComplaintAction(id){var x=O.complaints.find(function(z){return z.id===id});if(x){x.status=x.status==='待受理'?'处理中':'已关闭';audit('更新投诉状态','投诉',id,x.status);msg('投诉状态已更新，改进记录已保留')}}
  function v141Keywords(){detail={type:'keywords'};renderAll()}
  function adminKeywords(){return T('投诉关键词总结','来源：当前投诉列表 · 生成时间 '+now(),B('返回投诉分析','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-kv"><div><label>高频关键词</label><strong>等待时间长、预约困难、号源不足</strong></div><div><label>主要影响环节</label><strong>门诊候诊、号源管理、报告提醒</strong></div><div><label>建议动作</label><strong>优化过号提醒、增加晚间号源、提高报告超时预警</strong></div></div><div class="actions">'+B('确认关键词','v141ConfirmKeywords()','btn primary')+B('创建改进任务','v141CreateImprovement()','btn primary')+'</div></div>'}
