  function patientQueue(){var a=STORE.appointments[0];return '<div class="mhead"><button class="btn sm" onclick="v141PatientTab(\'progress\')">‹ 返回进度</button><h1>提前取号</h1></div><div class="mcard"><h2>'+(a?a.doctor+' · '+a.dept:'暂无有效预约')+'</h2><p class="sub">开放时间：就诊前 15 分钟；取号后请按时到院扫码签到。</p>'+(a?'<div class="v11-info">预约号：'+a.number+'<br>时间：'+a.date+' '+a.time+'</div>'+(S.queueStatus==='已取号'?'<div class="mcard blue"><h2>取号成功</h2><p>请在机器上扫描下方二维码签到</p><strong style="font-size:28px;letter-spacing:4px">'+S.queueCode+'</strong></div>'+B('刷新二维码','v141PatientTakeNumber()','btn primary'):B('立即取号并生成二维码','v141PatientTakeNumber()','btn primary')):'<div class="v11-info">请先完成预约挂号。</div>')+'</div>'+patientNav('progress')+'</div>'}
