  function patientAI(){return '<div class="mhead"><div><h1>健康服务</h1><span class="sub">AI 仅生成健康宣教草稿，不替代医生诊断</span></div></div><div class="mcard"><h2>健康宣教助手</h2><div class="v11-info">依据：已发布报告、医生方案、检查准备事项；同步时间：'+now()+'</div><div class="v11-form"><label>想了解什么？</label><input id="aiQuestion" placeholder="例如：检查后饮食和复查需要注意什么？"><button class="btn primary" onclick="v141AskAI()">生成健康宣教</button></div></div><div class="mcard"><h2>三种服务状态</h2><div class="item"><div><b>正常</b><small>展示宣教草稿、依据字段和来源时间</small></div>'+b('可生成','good')+'</div><div class="item"><div><b>依据不足</b><small>缺少有效报告或医生方案时停止生成</small></div>'+b('需人工咨询','warn')+'</div><div class="item"><div><b>服务不可用</b><small>保留线上医生/护士留言入口</small></div>'+b('可转人工','info')+'</div></div>'+patientNav('mine')+'</div>'}
  function v141AskAI(){var q=(document.getElementById('aiQuestion')||{}).value||'';if(!q){notice='请先填写问题';renderAll();return}notice='宣教草稿已生成，依据清单已展示；请确认后再推送';renderAll()} window.v141AskAI=v141AskAI;
  function patientFeedback(){return '<div class="mhead"><div><h1>留言与投诉</h1><span class="sub">服务留言进入线上回复；投诉进入管理闭环</span></div></div><div class="mcard"><h2>提交反馈</h2><div class="v11-form"><label>类型 *</label><select id="feedbackType"><option>服务留言</option><option>投诉</option></select><label>内容 *</label><textarea id="feedbackText" rows="4" placeholder="请描述需要回复或改进的问题"></textarea><button class="btn primary" onclick="v141SubmitFeedback()">提交并查看进度</button></div></div>'+patientNav('mine')+'</div>'}
