  function patientApp(){var pp=S.patientPage||'home';if(pp==='profile')return patientProfile();if(pp==='book')return patientBook();if(pp==='confirm')return patientConfirm();if(pp==='progress')return patientProgress();if(pp==='queue')return patientQueue();if(pp==='ai')return patientAI();if(pp==='feedback')return patientFeedback();if(pp==='mine')return patientMine();return patientHome()}
  function patientNav(a){return '<nav class="mbottom"><button class="'+(S.patientPage==='home'?'on':'')+'" onclick="v141PatientTab(\'home\')">⌂<br>预约挂号</button><button class="'+(S.patientPage==='progress'?'on':'')+'" onclick="v141PatientTab(\'progress\')">◷<br>就诊进度</button><button class="'+(S.patientPage==='mine'?'on':'')+'" onclick="v141PatientTab(\'mine\')">◎<br>我的</button></nav>'}
  function patientHome(){var q=S.patientQuery||'',days=['今日','10-14','10-15','10-16','10-17','10-18','10-19'],docs=D;return '<div class="mhead"><div><h1>预约挂号</h1><span class="sub">恩泽医院 · 未来 7 天专家号源</span></div><button class="btn sm" onclick="v141PatientTab(\'mine\')">我的</button></div><div class="msearch"><input value="'+e(q)+'" placeholder="搜索医生、科室或疾病关键词" oninput="V12_STATE.patientQuery=this.value;renderAll()"><button class="btn primary" onclick="renderAll()">搜索</button></div><div class="v11-chips">'+days.map(function(x,i){return '<button class="v11-chip '+(S.patientDay===i?'on':'')+'" onclick="V12_STATE.patientDay='+i+';renderAll()">'+x+'</button>'}).join('')+'</div><div class="mcard"><h2>专家号源</h2>'+docs.filter(function(d){return !q||d.name.includes(q)||d.dept.includes(q)||d.expertise.includes(q)}).slice(0,6).map(function(d){return '<button class="mcard doctor-card" '+(d.remaining===0?'disabled':'')+' onclick="v141PatientDoctor(\''+d.id+'\')"><span class="doc-avatar">'+d.photo+'</span><span><h3>'+d.name+' · '+d.title+'</h3><p>'+d.dept+' · 擅长 '+d.expertise+'</p><small>'+days[S.patientDay||0]+' · 剩余 '+d.remaining+' 号 · '+(d.remaining?'可预约':'暂无号源')+'</small></span><span class="mcta">›</span></button>'}).join('')+'</div><div class="mcard"><h2>科室号源</h2><div class="mgrid">'+['呼吸内科','心内科','消化内科','全科医学科'].map(function(x,i){return '<button onclick="V12_STATE.patientQuery=\''+x+'\';renderAll()"><strong>'+[12,8,6,16][i]+'</strong><span>'+x+' · 剩余号源</span></button>'}).join('')+'</div></div>'+patientNav('home')+'</div>'}
