  patientHome=function(){var q=S.patientQuery||'',ordinary=S.patientMode==='ordinary',docs=ordinary?P_ORDINARY:D,days=['今日','10-16','10-17','10-18','10-19','10-20','10-21'];return '<div class="mhead"><div><h1>预约挂号</h1><span class="sub">专家门诊与普通门诊均可预约</span></div><button class="btn sm" onclick="v141PatientTab(\'mine\')">我的</button></div><div class="v11-chips"><button class="v11-chip '+(!ordinary?'on':'')+'" onclick="V12_STATE.patientMode=\'expert\';renderAll()">专家门诊</button><button class="v11-chip '+(ordinary?'on':'')+'" onclick="V12_STATE.patientMode=\'ordinary\';renderAll()">普通门诊</button></div><div class="msearch"><input value="'+e(q)+'" placeholder="搜索医生、科室或疾病关键词" oninput="V12_STATE.patientQuery=this.value;renderAll()"><button class="btn primary" onclick="renderAll()">搜索</button></div><div class="v11-chips">'+days.map(function(x,i){return '<button class="v11-chip '+(S.patientDay===i?'on':'')+'" onclick="V12_STATE.patientDay='+i+';renderAll()">'+x+'</button>'}).join('')+'</div><div class="mcard"><h2>'+ (ordinary?'普通门诊号源':'专家号源') +'</h2>'+docs.filter(function(d){return !q||d.name.includes(q)||d.dept.includes(q)||d.expertise.includes(q)}).slice(0,6).map(function(d){return '<button class="mcard doctor-card" onclick="v141PatientDoctor(\''+d.id+'\')"><span class="doc-avatar">'+d.photo+'</span><span><h3>'+d.name+' · '+d.title+'</h3><p>'+d.dept+' · 擅长 '+d.expertise+'</p><small>'+days[S.patientDay||0]+' · 剩余 '+d.remaining+' 号 · 可预约</small></span><span class="mcta">›</span></button>'}).join('')+'</div><div class="mcard"><h2>热门科室号源</h2><div class="mgrid">'+['呼吸内科','全科医学科','消化内科','心内科'].map(function(x,i){return '<button onclick="V12_STATE.patientQuery=\''+x+'\';V12_STATE.patientMode=\'ordinary\';renderAll()"><strong>'+[12,18,12,8][i]+'</strong><span>'+x+' · 普通门诊号源</span></button>'}).join('')+'</div></div>'+patientNav('home')+'</div>'};
