  function patientProgress(){var a=STORE.appointments[0],steps=a?['预约成功','签到/候诊','医生接诊','检查预约','检查/报告','复查安排']:[];return '<div class="mhead"><div><h1>就诊进度</h1><span class="sub">时间轴与当前业务状态一致</span></div></div><div class="msearch"><input placeholder="姓名 / 预约号" oninput="V12_STATE.patientQuery=this.value;renderAll()"><button class="btn primary" onclick="renderAll()">搜索</button></div><div class="mcard">'+(a?'<h2>'+a.doctor+' · '+a.dept+'</h2><p class="sub">'+a.date+' '+a.time+' · 预约号 '+a.number+'</p><div class="v11-steps">'+steps.map(function(x,i){return '<div class="v11-step '+(i===0?'done':i===1?'cur':'')+'">'+x+'</div>'}).join('')+'</div><div class="v11-info">当前状态：'+a.status+'。签到后进入候诊，检查和报告状态由医院端同步。</div>':'<div class="v11-info">暂无匹配预约，请先完成预约挂号。</div>')+'</div><div class="mcard"><h2>检查与报告</h2><div class="item"><div><b>报告状态</b><small>医技发布后将展示结果、参考区间和异常标记</small></div>'+b(STORE.reports.find(function(x){return x.patientId===(S.patientId||'8A01')})||null&&STORE.reports.find(function(x){return x.patientId===(S.patientId||'8A01')})||null.status||'待生成','warn')+'</div></div>'+patientNav('progress')+'</div>'}
