  patientHome=function(){var a=STORE.appointments[0],ready=!!S.patientProfile;return '<div class="mhead"><div><span class="sub">V 端 / 预约、取号、签到、检查与报告</span><h1>患者入口</h1><span class="sub">门诊服务</span></div><button class="btn sm" onclick="v141PatientTab(\'mine\')">我的</button></div>'+fusionPatientContext()+'<div class="mcard"><div class="head"><div><h2>欢迎进入患者服务</h2><p class="sub">从个人信息、预约挂号到就诊进度，所有页面共享当前就诊上下文。</p></div>'+b(ready?'信息已完成':'信息未完成',ready?'good':'warn')+'</div><div class="fusion-metrics"><div><label>当前患者</label><strong>'+(S.patientName||'未完成信息')+'</strong><small>PAT-1001</small></div><div><label>预约状态</label><strong>'+(a?'已预约':'未预约')+'</strong><small>返回后状态保留</small></div></div><div class="actions">'+B(ready?'查看/编辑个人信息':'先完善个人信息',"v141PatientTab('profile')",'btn primary')+B('预约挂号',"v141PatientTab('appointment')")+B('查看就诊进度',"v141PatientTab('progress')")+'</div></div>'+fusionPatientNav('appointment')+'</div>'};
  patientProgress=function(){var a=STORE.appointments[0],r=STORE.reports.find(function(x){return x.patientId===(S.patientId||'8A01')})||null,signed=S.queueStatus==='已取号';return '<div class="mhead"><div><span class="sub">V 端 / 预约、取号、签到、检查与报告</span><h1>就诊进度</h1></div><button class="btn sm" onclick="v141PatientTab(\'mine\')">我的</button></div>'+fusionPatientContext()+'<div class="mcard">'+(a?'<div class="head"><div><h2>'+a.doctor+' · '+a.dept+'</h2><p class="sub">'+a.date+' '+a.time+' · 预约号 '+a.number+'</p></div>'+b(signed?'已取号':'已预约',signed?'good':'warn')+'</div><div class="v11-steps"><div class="v11-step done">预约成功</div><div class="v11-step '+(signed?'done':'cur')+'">签到/候诊</div><div class="v11-step">医生接诊</div><div class="v11-step">检查/报告</div><div class="v11-step">复查安排</div></div><div class="v11-info">当前状态：'+(signed?'已取号，候诊状态待现场回写':'预约已确认；就诊前 15 分钟可提前取号')+'。</div><div class="actions">'+B('提前取号',"v141PatientTab('queue')",'btn primary')+B('查看检查与报告',"v141PatientTab('report')")+'</div>':'<div class="v11-info">暂无匹配预约，请先完成预约挂号。</div>')+'</div><div class="mcard"><h2>问题与服务</h2><div class="item"><div><b>检查与报告</b><small>'+(r?r.project+' · '+r.status:'医技发布后显示报告正文和参考区间')+'</small></div>'+b(r?'已发布':'待生成',r?'good':'warn')+'</div><div class="item"><div><b>健康服务</b><small>健康宣教草稿、依据清单和人工留言入口</small></div>'+B('查看',"v141PatientTab('ai')",'btn primary')+'</div></div>'+fusionPatientNav('progress')+'</div>'};
  patientMine=function(){return '<div class="mhead"><div><span class="sub">V 端 / 患者服务</span><h1>我的</h1><span class="sub">就诊人、授权与隐私</span></div></div>'+fusionPatientContext()+'<div class="mcard"><h2>就诊人信息</h2><div class="doctor-card"><span class="doc-avatar">'+(S.patientName||'我').slice(0,1)+'</span><span><h3>'+e(S.patientName||'本人就诊人')+'</h3><p>'+e(S.patientPhone||'演示手机号')+' · '+(S.patientProfile?'实名信息已绑定':'待完成实名信息')+'</p></span></div><div class="actions">'+B(S.patientProfile?'编辑信息':'完善信息',"v141PatientTab('profile')",'btn primary')+'</div></div><div class="mcard"><div class="item"><div><b>提前取号</b><small>就诊前 15 分钟取号并生成二维码</small></div>'+B('去取号',"v141PatientTab('queue')",'btn primary')+'</div><div class="item"><div><b>健康服务</b><small>AI 宣教草稿与线上人工咨询</small></div>'+B('查看',"v141PatientTab('ai')")+'</div><div class="item"><div><b>留言与投诉</b><small>分开提交并查看处理进度</small></div>'+B('进入',"v141PatientTab('feedback')")+'</div></div>'+fusionPatientNav('mine')+'</div>'};
  patientApp=function(){var pp=S.patientPage||'home';if(pp==='appointment')return fusionOriginalPatientHome();if(pp==='profile')return patientProfile();if(pp==='book')return patientBook();if(pp==='confirm')return patientConfirm();if(pp==='progress')return patientProgress();if(pp==='report')return patientReport();if(pp==='queue')return patientQueue();if(pp==='ai')return patientAI();if(pp==='feedback')return patientFeedback();if(pp==='mine')return patientMine();return patientHome()};
  function nurseTasks(){var mode=S.sub||'all',rows=STORE.patients.map(function(x,i){if(!x.nursingStatus)x.nursingStatus=i%3===0?'待处理':i%3===1?'处理中':'已完成';return x}).filter(function(x){return mode==='all'||mode==='pending'&&x.nursingStatus==='待处理'||mode==='processing'&&x.nursingStatus==='处理中'||mode==='done'&&x.nursingStatus==='已完成'});return T('护理任务','检查准备、报告追踪和复查协助按处理状态分流')+'<div class="v11-card">'+rowTable(['📌住院号','患者/床位','任务','状态','操作'],rows.map(function(x){return '<tr><td>'+x.id+'</td><td>'+x.name+'<br>'+x.bed+'</td><td>'+x.next+'</td><td>'+b(x.nursingStatus,x.nursingStatus==='已完成'?'good':x.nursingStatus==='处理中'?'warn':'info')+'</td><td>'+(x.nursingStatus==='已完成'?B('查看患者','v14OpenPatient("'+x.id+'")'):B(x.nursingStatus==='待处理'?'开始处理':'完成任务','v141NursingAction("'+x.id+'")','btn primary'))+'</td></tr>'}))+'</div>'}
  function v141NursingAction(id){var x=p(id);x.nursingStatus=x.nursingStatus==='待处理'?'处理中':'已完成';x.updated=now();audit('更新护理任务','患者',id,x.nursingStatus);msg('护理任务状态已更新，并同步患者列表和消息中心')}
  function nurseTimeline(){var q=S.query||'',rows=STORE.patients.filter(function(x){return !q||x.name.includes(q)||x.id.includes(q)});return T('患者时间轴','检查预约、准备、送检、检查中和报告生成使用统一患者状态',B('新增流程节点','v141TimelineForm()','btn primary'))+'<div class="v11-card"><div class="filters"><input id="timelineQ" value="'+e(q)+'" placeholder="姓名 / 住院号"><button class="btn primary" onclick="v141TimelineSearch()">搜索</button></div>'+rows.map(function(x){var exam=STORE.exams.find(function(z){return z.patientId===x.id});return '<div class="v11-card"><div class="head"><h2>'+x.name+' · '+x.id+' · '+x.bed+'</h2>'+b(x.stage)+'</div><div class="timeline"><div class="step done">预约检查</div><div class="step '+(exam&&exam.status==='已预约'?'cur':'done')+'">准备</div><div class="step '+(exam&&exam.status==='检查中'?'cur':exam&&exam.status==='已完成'?'done':'')+'">送检/检查中</div><div class="step '+(x.report==='待出报告'?'cur':x.report!=='—'?'done':'')+'">报告生成</div><div class="step '+(x.stage==='复查待安排'?'cur':'')+'">复查安排</div></div><div class="v11-info">当前说明：'+x.next+' · 更新时间 '+x.updated+'</div></div>'}).join('')+'</div>'}
  function v141TimelineSearch(){S.query=(document.getElementById('timelineQ')||{}).value||'';renderAll()}
  function v141TimelineForm(){detail={type:'timeline-add'};renderAll()}
  function timelineForm(){return T('新增流程节点','节点提交后同步患者时间轴、检查列表和报告状态',B('返回患者时间轴','v141CloseDetail()'))+'<div class="v11-card"><div class="v11-form"><label>患者 *</label><select id="tlPatient">'+STORE.patients.map(function(x){return '<option value="'+x.id+'">'+x.name+' · '+x.id+'</option>'}).join('')+'</select><label>节点 *</label><select id="tlNode"><option>检查准备完成</option><option>患者已送检</option><option>检查完成</option><option>报告已生成</option></select><label>记录说明 *</label><textarea id="tlNote" rows="3" placeholder="填写操作者和业务结果"></textarea><button class="btn primary" onclick="v141AddTimeline()">提交节点并同步</button></div></div>'}
  function v141AddTimeline(){var id=document.getElementById('tlPatient').value,node=document.getElementById('tlNode').value,note=(document.getElementById('tlNote')||{}).value||node,x=p(id),exam=STORE.exams.find(function(z){return z.patientId===id});x.timeline=x.timeline||[];x.timeline.push({node:node,time:now(),note:note});if(node==='患者已送检'&&exam){exam.status='检查中';x.stage='检查中'}if(node==='检查完成'&&exam){exam.status='已完成';x.stage='报告待查看'}if(node==='报告已生成'){x.report='已出结果待护士查看';x.stage='报告待查看'}x.next=note;x.updated=now();audit('新增时间轴节点','患者',id,node);msg('流程节点已同步患者时间轴、检查列表和报告状态')}
  function nurseAnalytics(){var s=S.sub||'efficiency';if(s==='checks')return T('检查量','按项目展示检查预约量和完成量，支持周期筛选',B('导出检查量','v14ExportTasks()','btn primary'))+'<div class="v11-card"><h2>近 7 日检查量</h2>'+scaledChart([18,22,16,25,21,28,24],['一','二','三','四','五','六','日'],'单')+'</div>';if(s==='reports')return T('报告时效','按科室展示检查完成至报告发布的耗时',B('导出报告时效','v14ExportTasks()','btn primary'))+'<div class="v11-card"><h2>报告平均耗时</h2>'+scaledChart([72,80,63,91],['影像','检验','超声','病理'],'分钟')+'</div>';return T('诊疗效率','预约至检查、检查至报告、危急值响应分别计算',B('导出诊疗效率','v14ExportTasks()','btn primary'))+pageStats([['预约→检查','82 分钟','近 7 日 -8 分钟',''],['检查→报告','36 分钟','达标率 94%',''],['危急值响应','7 分钟','目标 ≤ 10 分钟','']])+'<div class="v11-card"><h2>近 7 日诊疗时效</h2>'+scaledChart([72,64,78,70,66,61,58],['一','二','三','四','五','六','日'],'分钟')+'</div>'}
  var BOARD_PUBLIC=true;
  function nurseBoard(){var rows=STORE.patients.filter(function(x){return x.exam&&x.exam!=='—'});return T('护士站电子白板',BOARD_PUBLIC?'家属提示模式 · 不展示诊断、报告正文或异常数值':'护士模式 · 可处理病区任务',B(BOARD_PUBLIC?'切换护士模式':'切换家属提示模式','v141ToggleBoard()','btn primary'))+'<div class="v11-grid3"><div class="v11-stat"><small>检查中</small><strong>'+rows.filter(function(x){return x.stage==='检查中'}).length+'</strong></div><div class="v11-stat"><small>待出报告</small><strong>'+rows.filter(function(x){return x.report==='待出报告'}).length+'</strong></div><div class="v11-stat"><small>报告待查看</small><strong>'+rows.filter(function(x){return x.report&&x.report.indexOf('已出')>=0}).length+'</strong></div></div><div class="v11-card"><h2>检查与报告进度</h2>'+rowTable(['📌床位','患者','检查项目','当前状态','服务提示','操作'],rows.map(function(x){var name=BOARD_PUBLIC?x.name.slice(0,1)+'＊':x.name,ready=x.report&&x.report.indexOf('已出')>=0;return '<tr><td>'+x.bed+'</td><td>'+name+'</td><td>'+x.exam+'</td><td>'+b(ready?'报告已出':x.stage)+'</td><td>'+(ready?'报告已出，请责任护士查看':x.stage==='检查中'?'检查进行中，请耐心等候':'等待检查安排')+'</td><td>'+(BOARD_PUBLIC?'—':B('处理任务','v14OpenPatient("'+x.id+'")','btn primary'))+'</td></tr>'}))+'</div>'}
